  --halo-highlight-multiplier: 1.20;
  --halo-glow-spread: 36px;
}

@keyframes halo-indeterminate {
  0% {
    transform: translateX(-100%);
  }
  50% {
    transform: translateX(100%);
  }
  100% {
    transform: translateX(300%);
  }
}

.animate-indeterminate-slide {
